fn swap3(a: &mut Vec<i32>, h: usize, i: usize, j: usize) {
    // Read the original values at the three distinct positions.
    let v_h = a[h];
    let v_i = a[i];
    let v_j = a[j];

    // Perform the 3‐cycle reassignment:
    // a[h] ← original a[i], a[i] ← original a[j], a[j] ← original a[h]
    a[h] = v_i;
    a[i] = v_j;
    a[j] = v_h;
}

